import { tv, type VariantProps } from "@/lib/beton/tv";

export const toast = tv({
  slots: {
    viewport: [
      "fixed right-4 bottom-4 z-[60] flex w-[calc(100vw-2rem)] flex-col-reverse gap-3 outline-none",
      "sm:right-6 sm:bottom-6 sm:w-96",
    ],
    root: [
      "relative flex w-full items-start gap-3 border-3 border-border bg-raised p-4 pr-14 text-foreground shadow-sm outline-none",
      "data-[type=success]:bg-success data-[type=error]:bg-danger data-[type=warning]:bg-secondary data-[type=info]:bg-primary",
      "data-limited:hidden",
    ],
    content: "flex min-w-0 flex-1 flex-col gap-1",
    title: "font-display text-base font-extrabold leading-tight",
    description: "text-sm",
    actions: "mt-2 flex flex-wrap gap-2",
    close: "absolute top-2 right-2",
  },
});

export type ToastVariants = VariantProps<typeof toast>;

"use client";

import { Toast as BaseToast } from "@base-ui/react/toast";
import { button } from "@/lib/beton/recipes/button.recipe";
import { toast } from "@/lib/beton/recipes/toast.recipe";
import type { ReactNode } from "react";
import { CloseIcon } from "@/lib/beton/icons";

export interface ToastProviderProps extends Omit<BaseToast.Provider.Props, "children"> {
  children: ReactNode;
  /** Accessible name of each toast's dismiss button. */
  closeLabel?: string;
}

/**
 * Hosts the toast queue and renders the stack. Put it once, near the root of
 * your app, then call useToast() anywhere below it.
 */
export function ToastProvider({
  children,
  closeLabel = "Dismiss notification",
  ...props
}: ToastProviderProps) {
  const styles = toast();
  return (
    <BaseToast.Provider {...props}>
      {children}
      <BaseToast.Portal>
        <BaseToast.Viewport className={styles.viewport()}>
          <ToastList closeLabel={closeLabel} />
        </BaseToast.Viewport>
      </BaseToast.Portal>
    </BaseToast.Provider>
  );
}

function ToastList({ closeLabel }: { closeLabel: string }) {
  const styles = toast();
  const { toasts } = BaseToast.useToastManager();

  return toasts.map((item) => (
    <BaseToast.Root key={item.id} toast={item} className={styles.root()}>
      <BaseToast.Content className={styles.content()}>
        <BaseToast.Title className={styles.title()} />
        <BaseToast.Description className={styles.description()} />
        {item.actionProps ? (
          <div className={styles.actions()}>
            <BaseToast.Action className={button({ variant: "secondary", size: "sm" })} />
          </div>
        ) : null}
      </BaseToast.Content>
      <BaseToast.Close
        aria-label={closeLabel}
        className={button({
          variant: "ghost",
          size: "sm",
          iconOnly: true,
          class: styles.close(),
        })}
      >
        <CloseIcon width={16} height={16} />
      </BaseToast.Close>
    </BaseToast.Root>
  ));
}

/**
 * Adds, updates and closes toasts. Set `type` to "success", "error",
 * "warning" or "info" to colour the toast.
 */
export const useToast = BaseToast.useToastManager;

/** Creates a manager for showing toasts from outside React. */
export const createToastManager = BaseToast.createToastManager;
